var n=`0079-mamaliga`;var t=`world-0079`;var s=`RO`;var a=`eastern-europe`;var r=4;var o=36;var g={en:`Mămăligă`,ua:`Мамалиґа`};var m={en:`A classic dish from Romania, featuring corn grits, bryndza, sour cream. A practical home-kitchen version with measured step ingredients and clear cooking methods.`,ua:`Класична страва з Румунія. Основні складники: кукурудзяна крупа, бринза, сметана. Домашній варіант із поетапними діями та точними кількостями продуктів.`};var l=[{en:`Combine these ingredients in a pot, bring just to a boil and skim any foam. Simmer gently for about 5 minutes to make a flavorful base.`,ua:`З’єднайте складники в каструлі, доведіть майже до кипіння та зніміть піну. Варіть на малому вогні приблизно 5 хвилин для насиченої основи.`,t:[`simmering`,`skimming-foam`],m:5,i:[[`water`,1100,`ml`],[`table-salt`,4,`g`]]},{en:`Slowly stir the grains into the simmering liquid; cook over low heat for about 25 minutes, stirring to prevent sticking.`,ua:`Повільно всипте крупу в гарячу рідину; варіть на слабкому вогні приблизно 25 хвилин, помішуючи, щоб не пристала до дна.`,t:[`absorption-cooking`],m:25,i:[[`corn-grits`,250,`g`]]},{en:`Stir in these seasonings and additions. Taste, adjust the balance and let the dish stand briefly before serving.`,ua:`Додайте приправи та завершальні складники. Спробуйте, збалансуйте смак і дайте страві трохи настоятися перед подаванням.`,t:[`seasoning`,`finishing-with-herbs`],m:4,i:[[`unsalted-butter`,75,`g`],[`bryndza`,165,`g`]]},{en:`Finish with the listed ingredients, check seasoning and serve immediately.`,ua:`Додайте завершальні складники, перевірте смак і відразу подавайте.`,t:[`seasoning`,`garnishing`],m:2,i:[[`sour-cream`,80,`g`]]}];var d={slug:n,id:t,country:`RO`,region:a,servings:4,minutes:36,title:g,text:m,steps:l};export{s as country,d as default,t as id,o as minutes,a as region,r as servings,n as slug,l as steps,m as text,g as title};